param(
  [string]$RepoFullName = 'cagdascagdas100/chat_gpt_clone_1',
  [string]$MainBranch = 'main',
  [string]$ControllerRoot = 'C:\Users\cagda\Documents\GitHub\AAYS_SHARED_RUNNER_CONTROL_main',
  [string]$WorkRoot = 'C:\Users\cagda\Documents\GitHub',
  [int]$MaxTasks = 1
)
$ErrorActionPreference = 'Stop'
$Summary = [ordered]@{ queue_seen=$false; queue_started=$false; single_runner_lock_acquired=$true; controller_sync_ok=$false; task_runs_in_clean_worktree=$false; allowed_paths_enforced=$false; runner_output_uploaded=$false; post_sync_ok=$false; PUSH_SYNC_OK=$false; CONTINUE_RUNNER_READY=$false; final_ready=$false; fake_data=$false; db_write=$false; migration=$false; production_deploy=$false; blockers=@(); processed=@() }
function N { (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
function SD($p){ if($p -and !(Test-Path -LiteralPath $p)){ New-Item -ItemType Directory -Force -Path $p | Out-Null } }
function W($p,$c){ SD (Split-Path -Parent $p); [IO.File]::WriteAllText($p,$c,[Text.UTF8Encoding]::new($false)) }
function J($o){ $o|ConvertTo-Json -Depth 30 }
function R($p){ (($p -replace '\\','/').TrimStart('/')) }
function S($v){ (($v -replace '[^A-Za-z0-9_.-]','_').Trim('_')) }
function B($c){ if(-not ($Summary.blockers -contains $c)){ $Summary.blockers += $c } }
function G { param([Parameter(ValueFromRemainingArguments=$true)][string[]]$A) if(!$A){throw 'NO_GIT_ARGS'}; $o=& git @A 2>&1; [pscustomobject]@{code=$LASTEXITCODE;out=(($o|Out-String).Trim());args=$A} }
function OK($r,$b){ if($r.code -ne 0){ throw ($b + ': ' + $r.out) } }
function GP($o,$n){ if($null -eq $o){return $null}; $p=$o.PSObject.Properties[$n]; if($p){return $p.Value}; return $null }
function AB($v){ if($v -is [bool]){return $v}; if($null -eq $v){return $false}; return ([string]$v).Trim().ToLowerInvariant() -in @('true','1','yes','y') }
function PL($v){ if($null -eq $v){return @()}; if($v -is [Array]){return @($v|%{R ([string]$_)}|?{$_})}; return @(([string]$v -split '[,;]'|%{R $_}|?{$_})) }
function Allowed($p,$a){ $x=R $p; foreach($y in $a){$z=(R $y).TrimEnd('/'); if($x -eq $z -or $x.StartsWith($z+'/')){return $true}}; return $false }
function SyncRepo($root,$branch){ $url='https://github.com/'+$RepoFullName+'.git'; SD (Split-Path -Parent $root); if(!(Test-Path -LiteralPath $root)){ OK (G clone --branch $branch --single-branch $url $root) 'CLONE_FAILED' }; Push-Location $root; try{ OK (G status --porcelain) 'STATUS_FAILED'; $dirty=(G status --porcelain).out; if($dirty){ throw 'WORKTREE_DIRTY' }; OK (G fetch origin $branch) 'FETCH_FAILED'; OK (G checkout $branch) 'CHECKOUT_FAILED'; OK (G rebase ('origin/'+$branch)) 'REBASE_FAILED' } finally{ Pop-Location } }
function ReadQ($f){ $raw=Get-Content -LiteralPath $f.FullName -Raw; if($f.Extension -ieq '.json'){ return $raw|ConvertFrom-Json }; $m=[ordered]@{}; foreach($line in ($raw -split "`r?`n")){ $t=$line.Trim(); if(!$t -or $t.StartsWith('#') -or $t -notmatch '='){continue}; $i=$t.IndexOf('='); $m[$t.Substring(0,$i).Trim()]=$t.Substring($i+1).Trim() }; [pscustomobject]$m }
function ValidQ($f,$root){ $d=ReadQ $f; $pg=[string](GP $d 'page_key'); $sp=[string](GP $d 'script_path'); $br=[string](GP $d 'target_branch'); $tid=[string](GP $d 'task_id'); if(!$tid){$tid=[IO.Path]::GetFileNameWithoutExtension($f.Name)}; $st=[string](GP $d 'status'); if(!$st){$st='queued'}; $ap=PL (GP $d 'allowed_paths'); $bad=@(); if(!$pg){$bad+='MISSING_page_key'}; if(!$sp){$bad+='MISSING_script_path'}; if(!$br){$bad+='MISSING_target_branch'}; if($ap.Count -eq 0){$bad+='MISSING_allowed_paths'}; foreach($flag in @('no_fake_final_ready','no_db_write','no_migration','no_production_deploy')){ if(!(AB (GP $d $flag))){$bad+='MISSING_'+$flag} }; $rel=R ($f.FullName.Substring($root.Length).TrimStart('\','/')); if($pg -and !$rel.StartsWith((R "docs/chatgpt_status/$pg/queue")+'/')){$bad+='PAGE_KEY_PATH_MISMATCH'}; [pscustomobject]@{valid=($bad.Count -eq 0);blockers=$bad;page_key=$pg;script_path=$sp;target_branch=$br;task_id=(S $tid);status=$st;allowed_paths=$ap;queue_rel=$rel;data=$d} }
function Changed($root){ Push-Location $root; try{ $r=G status --porcelain; OK $r 'STATUS_FAILED'; $p=@(); foreach($l in @($r.out -split '\r?\n'|?{$_})){ if($l.Length -ge 4){$q=$l.Substring(3).Trim().Trim('"'); if($q -match ' -> '){$q=($q -split ' -> ')[-1]}; $p+=R $q }}; return $p } finally{Pop-Location} }
function Stage($root,$allowed){ $ch=Changed $root; $un=@($ch|?{!(Allowed $_ $allowed)}); if($un.Count){return [pscustomobject]@{ok=$false;un=$un;ch=$ch}}; Push-Location $root; try{ foreach($p in $ch){ OK (G add -- $p) 'ADD_FAILED' } } finally{Pop-Location}; [pscustomobject]@{ok=$true;un=@();ch=$ch} }
function BrowserGate(){ $node=Get-Command node -ErrorAction SilentlyContinue; $npm=Get-Command npm -ErrorAction SilentlyContinue; $edge=@("$env:ProgramFiles (x86)\Microsoft\Edge\Application\msedge.exe","$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe","$env:LOCALAPPDATA\Microsoft\Edge\Application\msedge.exe")|?{Test-Path -LiteralPath $_}|select -First 1; $site=$false; try{$r=Invoke-WebRequest -UseBasicParsing -Uri 'http://127.0.0.1:8020/TerraYield_England_Program_Parcel_Layer_Matrix_20260629.html?refresh=v2' -TimeoutSec 5; $site=($r.StatusCode -ge 200 -and $r.StatusCode -lt 400)}catch{}; [pscustomobject]@{node_exists=[bool]$node;npm_exists=[bool]$npm;edge_exists=[bool]$edge;site_8020_ok=$site;browser_smoke_passed=([bool]$node -and [bool]$npm -and [bool]$edge -and $site)} }
function DoTask($t){ $Summary.queue_started=$true; $pg=$t.page_key; $tid=$t.task_id; $allowed=@($t.allowed_paths + @("docs/chatgpt_status/$pg/status/","docs/chatgpt_status/$pg/heartbeat/","docs/chatgpt_status/$pg/reports/","docs/chatgpt_status/$pg/runner_outputs/","docs/chatgpt_status/$pg/queue/")|%{R $_}|select -Unique); $bg=BrowserGate; if(!$bg.browser_smoke_passed){B 'BLOCKED_BROWSER_ENVIRONMENT'}; $wt=Join-Path $WorkRoot ('AAYS_'+(S $pg)+'_'+(S $tid)); SyncRepo $wt $t.target_branch; $Summary.task_runs_in_clean_worktree=$true; $script=Join-Path $wt ($t.script_path -replace '/','\'); if(!(Test-Path -LiteralPath $script)){throw 'SCRIPT_MISSING'}; $started="docs/chatgpt_status/$pg/status/${tid}_started.json"; $heart="docs/chatgpt_status/$pg/heartbeat/${tid}_heartbeat.txt"; $report="docs/chatgpt_status/$pg/reports/${tid}_runner_output.txt"; $done="docs/chatgpt_status/$pg/status/${tid}_completed.json"; $gate="docs/chatgpt_status/$pg/status/${tid}_gate.json"; W (Join-Path $wt ($started -replace '/','\')) (J ([ordered]@{task_id=$tid;page_key=$pg;queue_seen=$true;queue_started=$true;single_runner_lock_acquired=$true;task_runs_in_clean_worktree=$true;final_ready=$false;fake_data=$false})); W (Join-Path $wt ($heart -replace '/','\')) "TASK_ID=$tid`nPAGE_KEY=$pg`nSTATUS=running`nHEARTBEAT_AT=$(N)`n"; W (Join-Path $wt ($t.queue_rel -replace '/','\')) (J ([ordered]@{task_id=$tid;page_key=$pg;status='running';script_path=$t.script_path;target_branch=$t.target_branch;allowed_paths=$t.allowed_paths;no_fake_final_ready=$true;no_db_write=$true;no_migration=$true;no_production_deploy=$true})); OK (G -C $wt ls-remote origin) 'AUTH_FETCH_FAILED'; OK (G -C $wt push --dry-run origin ('HEAD:'+$t.target_branch)) 'AUTH_PUSH_FAILED'; $oldRoot=$env:AAYS_REPO_ROOT; $oldTask=$env:AAYS_TASK_ID; $env:AAYS_REPO_ROOT=$wt; $env:AAYS_TASK_ID=$tid; $out=$null; $ec=0; try{Push-Location $wt; try{$out=& powershell -NoProfile -ExecutionPolicy Bypass -File $script 2>&1; $ec=$LASTEXITCODE}finally{Pop-Location}}finally{$env:AAYS_REPO_ROOT=$oldRoot;$env:AAYS_TASK_ID=$oldTask}; if($ec -ne 0){B 'AUTOMATION_EXIT_NONZERO'}; $gpath=Join-Path $wt ($gate -replace '/','\'); $g=$null; if(Test-Path -LiteralPath $gpath){try{$g=Get-Content -LiteralPath $gpath -Raw|ConvertFrom-Json}catch{B 'GATE_PARSE_FAILED'}}; if(!$g){$g=[pscustomobject]@{source_row_gate_passed=$false;ui_token_gate_passed=$false;browser_smoke_passed=$bg.browser_smoke_passed;post_sync_ok=$false;manual_review_required=$true;fake_data=$false}; W $gpath (J $g)}; W (Join-Path $wt ($report -replace '/','\')) "TASK_ID=$tid`nPAGE_KEY=$pg`nbrowser_smoke_passed=$($bg.browser_smoke_passed)`nautomation_exit_code=$ec`nfake_data=false`n--- output ---`n$($out|Out-String)"; $st=Stage $wt $allowed; if(!$st.ok){throw ('UNSCOPED_CHANGES '+($st.un -join ','))}; $Summary.allowed_paths_enforced=$true; Push-Location $wt; try{ $cached=(G diff --cached --name-only).out; if($cached){OK (G commit -m "AAYS shared runner output $pg $tid") 'COMMIT_FAILED'}; OK (G fetch origin $t.target_branch) 'POST_FETCH_FAILED'; OK (G rebase ('origin/'+$t.target_branch)) 'POST_REBASE_FAILED'; OK (G push origin ('HEAD:'+$t.target_branch)) 'POST_PUSH_FAILED' } finally{Pop-Location}; $Summary.runner_output_uploaded=$true; $Summary.post_sync_ok=$true; $Summary.PUSH_SYNC_OK=$true; $final=$false; W (Join-Path $wt ($done -replace '/','\')) (J ([ordered]@{task_id=$tid;page_key=$pg;completed_at=N;queue_seen=$true;queue_started=$true;single_runner_lock_acquired=$true;task_runs_in_clean_worktree=$true;allowed_paths_enforced=$true;runner_output_uploaded=$true;post_sync_ok=$true;PUSH_SYNC_OK=$true;CONTINUE_RUNNER_READY=$true;browser_environment=$bg;final_ready=$final;fake_data=$false;blockers=$Summary.blockers})); W (Join-Path $wt ($t.queue_rel -replace '/','\')) (J ([ordered]@{task_id=$tid;page_key=$pg;status='done';PUSH_SYNC_OK=$true;CONTINUE_RUNNER_READY=$true;final_ready=$false;no_fake_final_ready=$true;no_db_write=$true;no_migration=$true;no_production_deploy=$true})); W (Join-Path $wt ($heart -replace '/','\')) "TASK_ID=$tid`nPAGE_KEY=$pg`nSTATUS=completed`nPUSH_SYNC_OK=true`nCONTINUE_RUNNER_READY=true`nHEARTBEAT_AT=$(N)`n"; $st2=Stage $wt $allowed; if(!$st2.ok){throw ('UNSCOPED_CHANGES '+($st2.un -join ','))}; Push-Location $wt; try{ $cached2=(G diff --cached --name-only).out; if($cached2){OK (G commit -m "AAYS shared runner completion $pg $tid") 'COMPLETION_COMMIT_FAILED'; OK (G fetch origin $t.target_branch) 'COMPLETION_FETCH_FAILED'; OK (G rebase ('origin/'+$t.target_branch)) 'COMPLETION_REBASE_FAILED'; OK (G push origin ('HEAD:'+$t.target_branch)) 'COMPLETION_PUSH_FAILED'} } finally{Pop-Location}; $Summary.CONTINUE_RUNNER_READY=$true; return [pscustomobject]@{task_id=$tid;page_key=$pg;completed=$true;final_ready=$false} }

try{ SyncRepo $ControllerRoot $MainBranch; $Summary.controller_sync_ok=$true; $qs=@(Get-ChildItem -Path (Join-Path $ControllerRoot 'docs\chatgpt_status') -Recurse -File|?{$_.FullName -match '[\\/]queue[\\/]' -and $_.Extension -in @('.json','.txt')}); $Summary.queue_seen=($qs.Count -gt 0); $valid=@(); foreach($q in $qs){try{$valid += ValidQ $q $ControllerRoot}catch{B 'QUEUE_PARSE_FAILED'}}; $ready=@($valid|?{$_.valid -and @('queued','pending','retry_pending','failed_transient') -contains ([string]$_.status).ToLowerInvariant()}|sort queue_rel); if(!$ready){B 'NO_VALID_PENDING_QUEUE_ITEMS'}; foreach($t in ($ready|select -First $MaxTasks)){try{$Summary.processed += DoTask $t}catch{B 'RUNNER_TASK_FAILED'; $Summary.processed += [pscustomobject]@{task_id=$t.task_id;page_key=$t.page_key;error=$_.Exception.Message;final_ready=$false}}} } catch { B 'SHARED_RUNNER_FAILED'; $Summary.error=$_.Exception.Message }
$Summary.checked_at=N
Write-Output (J $Summary)
